import re
from decimal import Context, Decimal, InvalidOperation, ROUND_HALF_EVEN

MAX_AMOUNT = Decimal("1000000.00")
_CENT = Decimal("0.01")
# Plain decimal: optional sign, ASCII digits, optional fraction. No whitespace/exponent.
_PLAIN_DECIMAL = re.compile(r"[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)\Z", re.ASCII)
# Private context so the caller's/global decimal context is never used or mutated.
_CTX = Context(prec=60, rounding=ROUND_HALF_EVEN, traps=[InvalidOperation])


def _to_decimal(value):
    if isinstance(value, bool):
        raise ValueError("bool is not a valid amount")
    if isinstance(value, Decimal):
        return value
    if isinstance(value, int):
        return Decimal(int(value))
    if isinstance(value, str):
        if not _PLAIN_DECIMAL.match(value):
            raise ValueError(f"invalid amount string: {value!r}")
        return Decimal(value)
    raise ValueError(f"unsupported amount type: {type(value).__name__}")


def _check_cents(amount):
    """Return amount with exponent -2 if it is a finite value exactly in cents."""
    if not amount.is_finite():
        raise ValueError("amount must be finite")
    quantized = amount.quantize(_CENT, context=_CTX)
    if _CTX.compare(quantized, amount) != 0:
        raise ValueError("amount is not exactly representable in cents")
    return quantized


def parse_amount(value):
    amount = _to_decimal(value)
    if not amount.is_finite():
        raise ValueError("amount must be finite")
    if amount.is_zero():
        raise ValueError("amount must be nonzero")
    if amount.is_signed():
        raise ValueError("amount must be positive")
    if amount > MAX_AMOUNT:
        raise ValueError("amount exceeds 1000000.00")
    return _check_cents(amount)


def format_amount(value):
    return format(value, ".2f")
